package com.bank.median;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.Logger;

// Finds the median of two sorted amount lists for National Bank of India.
public class MedianFinder {
    private static final Logger log = Logger.getLogger(MedianFinder.class.getName());
    private static final BigDecimal TWO = new BigDecimal("2");

    // Median of two sorted arrays. O(log min(m,n)), O(1).
    public BigDecimal medianOfTwo(BigDecimal[] a, BigDecimal[] b) {
        // Always binary-search the SMALLER array.
        if (a.length > b.length) {
            return medianOfTwo(b, a);
        }
        int m = a.length, n = b.length;
        int half = (m + n + 1) / 2;         // size of the left half
        int lo = 0, hi = m;
        while (lo <= hi) {
            int i = (lo + hi) / 2;          // cut in A
            int j = half - i;               // forced cut in B
            BigDecimal aLeft  = (i == 0) ? min() : a[i - 1];
            BigDecimal aRight = (i == m) ? max() : a[i];
            BigDecimal bLeft  = (j == 0) ? min() : b[j - 1];
            BigDecimal bRight = (j == n) ? max() : b[j];
            if (aLeft.compareTo(bRight) <= 0 && bLeft.compareTo(aRight) <= 0) {
                BigDecimal median;
                if (((m + n) & 1) == 1) {
                    median = aLeft.max(bLeft);          // odd total
                } else {
                    median = aLeft.max(bLeft)
                             .add(aRight.min(bRight))
                             .divide(TWO, 2, RoundingMode.HALF_UP); // even total
                }
                final BigDecimal result = median;
                log.info(() -> "Median = " + result);
                return median;
            } else if (aLeft.compareTo(bRight) > 0) {
                hi = i - 1;                 // took too many from A
            } else {
                lo = i + 1;                 // took too few from A
            }
        }
        throw new IllegalArgumentException("inputs not sorted");
    }

    private BigDecimal min() { return new BigDecimal("-1E18"); } // -infinity sentinel
    private BigDecimal max() { return new BigDecimal("1E18"); }  // +infinity sentinel
}
