package com.bank.median;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: median of Rajesh's and Priya's amount lists.
public class MedianDemo {
    private static final Logger log = Logger.getLogger(MedianDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        MedianFinder finder = new MedianFinder();

        BigDecimal[] rajesh = { bd("1000"), bd("3000") };        // sorted
        BigDecimal[] priya  = { bd("2000") };                     // sorted
        // Combined [1000,2000,3000] → median 2000 (odd total).
        log.info(() -> "Odd median = " + finder.medianOfTwo(rajesh, priya));

        BigDecimal[] a = { bd("1000"), bd("2000") };
        BigDecimal[] b = { bd("3000"), bd("4000") };
        // Combined [1000,2000,3000,4000] → median 2500 (even total).
        log.info(() -> "Even median = " + finder.medianOfTwo(a, b));
    }
}
